/**
 * Native addons as wasm: running napi-rs `wasm32-wasi` bindings in a box.
 *
 * Rust tools on npm (Rolldown and so Vite 8, Oxc, Tailwind v4's oxide, unrs-resolver, ...)
 * ship a native `.node` addon per platform, which a box can never load, plus a
 * `<pkg>-wasm32-wasi` package built with napi-rs: the same addon compiled to WebAssembly with
 * threads (`wasm32-wasip1-threads`). That package's loader (`*.wasi.cjs`, generated by the
 * napi-rs CLI) is written for Node and needs, besides plain JS:
 *
 * - `node:wasi`, for the addon's file and clock access;
 * - `node:worker_threads`, a real thread for every wasm thread, sharing one
 *   `WebAssembly.Memory`.
 *
 * When the box loads such a loader, it gets Lifo's versions of those two instead (see
 * node.ts, which asks `isNapiWasiLoader`):
 *
 * - `wasi` is the runtime's own WASI (`@napi-rs/wasm-runtime`, i.e. @tybys/wasm-util) on the
 *   box's fs, so the addon reads and writes the box's files.
 * - `worker_threads.Worker` starts a real host thread (Node `worker_threads` on a Node host, a
 *   Web Worker in a browser) running ./thread.ts, which loads the package's own runtime and
 *   reaches the box's fs through blocking requests that ./fs-server.ts answers.
 *
 * The loader itself runs unmodified, so every napi-rs version's options (memory size,
 * emnapi plugins, crash handling) apply as their authors wrote them.
 *
 * Threads need SharedArrayBuffer: always there on Node, in a browser only on a
 * cross-origin isolated page. Without them, requiring the loader fails at once, before it
 * allocates its shared memory, so packages with a JS fallback take it.
 */

import { EventEmitter } from '../events.js';
import type { ActivityTracker } from '../activity.js';
import { createFsServer, type FsServer } from './fs-server.js';
import { NAPI_WASI_THREAD_SOURCE } from './thread.js';

interface HostProcess {
	pid?: number;
	versions?: { node?: string };
	getBuiltinModule?: (id: string) => unknown;
}

// The host's own `process`, read when Lifo loads: on a Node host it's the real one (box code
// never replaces it there); in a browser there is none.
const HOST_PROCESS = (globalThis as { process?: HostProcess }).process;
const IS_NODE_HOST = !!HOST_PROCESS && typeof HOST_PROCESS.pid === 'number' && !!HOST_PROCESS.versions?.node;

interface NodeWorkerLike {
	threadId: number;
	on(event: string, fn: (...a: unknown[]) => void): void;
	postMessage(msg: unknown, transfer?: unknown[]): void;
	terminate(): Promise<number>;
	ref(): void;
	unref(): void;
}

interface NodeWorkerThreads {
	Worker: new (src: string, opts: Record<string, unknown>) => NodeWorkerLike;
}

function hostWorkerThreads(): NodeWorkerThreads | null {
	if (!IS_NODE_HOST || typeof HOST_PROCESS?.getBuiltinModule !== 'function') return null;
	try {
		return HOST_PROCESS.getBuiltinModule('node:worker_threads') as NodeWorkerThreads;
	} catch {
		return null;
	}
}

/** Why napi-rs wasm bindings can't run on this host, or null when they can. */
export function wasmThreadsUnavailable(): string | null {
	if (typeof SharedArrayBuffer === 'undefined' || typeof Atomics === 'undefined') {
		return IS_NODE_HOST
			? 'SharedArrayBuffer is unavailable in this Node.js'
			: 'the page is not cross-origin isolated (it needs COOP/COEP headers for SharedArrayBuffer)';
	}
	if (IS_NODE_HOST) {
		return hostWorkerThreads() ? null : 'it needs Node.js 20.16+ or 22.3+ (process.getBuiltinModule)';
	}
	// A page's main thread refuses what these addons do on their calling thread: a synchronous
	// compile over 8 MB (Rolldown's is 12) and Atomics.wait. A worker allows both.
	if (typeof (globalThis as { document?: unknown }).document !== 'undefined') {
		return "this box runs on the page's main thread, where browsers don't let WebAssembly wait or compile large modules synchronously (run the box in a Web Worker, WorkerSandbox, on a cross-origin isolated page)";
	}
	if (typeof Worker === 'undefined') return 'this host has no Web Workers';
	if ((globalThis as { crossOriginIsolated?: boolean }).crossOriginIsolated === false) {
		return 'the page is not cross-origin isolated (it needs COOP/COEP headers for SharedArrayBuffer)';
	}
	return null;
}

/**
 * Whether an error comes down to a wasm addon this host can't run (`ERR_LIFO_WASM_THREADS`,
 * already explained on stderr). napi-rs loaders wrap it as the `cause` of their own
 * "Cannot find native binding. npm has a bug..." error, which sends people the wrong way,
 * so the node runner prints nothing more for it.
 */
export function isWasmThreadsUnavailable(err: unknown): boolean {
	const seen = new Set<unknown>();
	const queue: unknown[] = [err];
	while (queue.length > 0 && seen.size < 64) {
		const e = queue.shift();
		if (!e || typeof e !== 'object' || seen.has(e)) continue;
		seen.add(e);
		if (Array.isArray(e)) { queue.push(...e); continue; }
		const r = e as { code?: unknown; message?: unknown; cause?: unknown; errors?: unknown };
		if (r.code === 'ERR_LIFO_WASM_THREADS') return true;
		// Newer loaders rebuild each load error from its message alone (createLoadErrorChain),
		// dropping the code; by then Lifo's loader has also prefixed the module's path.
		if (typeof r.message === 'string' && WASM_THREADS_MESSAGE.test(r.message)) return true;
		queue.push(r.cause, r.errors);
	}
	return false;
}

const WASM_THREADS_MESSAGE = /\[lifo\] \S+ needs WebAssembly threads, and /;

/**
 * Whether `source` is a napi-rs generated WASI loader (`<binding>.wasi.cjs`). Every napi-rs
 * version's loader requires `node:wasi` and `@napi-rs/wasm-runtime`.
 */
export function isNapiWasiLoader(source: string): boolean {
	return (
		(source.includes('@napi-rs/wasm-runtime') || source.includes('instantiateNapiModuleSync')) &&
		/require\(\s*['"](?:node:)?wasi['"]\s*\)/.test(source)
	);
}

/**
 * The napi-rs runtime a loader carries inside itself, as the source of a CommonJS module that
 * exports it; null when the loader requires `@napi-rs/wasm-runtime` instead. Newer napi-rs
 * loaders (rolldown 1.3.4, Nov 2026) bundle the runtime with its emnapi and @tybys/wasm-util,
 * and the binding package no longer depends on it. The bundle defines it as
 * `var require_runtime = __commonJSMin(...)` (exporting MessageHandler,
 * instantiateNapiModuleSync, WASI, ...) ahead of the binding's own code, with no requires.
 */
export function embeddedRuntimeSource(loader: string): string | null {
	const start = /\bvar (require_[\w$]+) = (?:\/\*[^*]*\*\/ )?__commonJSMin\(/g;
	for (let m = start.exec(loader); m; m = start.exec(loader)) {
		const end = loader.indexOf('\n}));', m.index);
		if (end === -1) return null;
		const body = loader.slice(m.index, end);
		if (/\bMessageHandler\b/.test(body) && /\binstantiateNapiModuleSync\b/.test(body) && /\bWASI\b/.test(body)) {
			return `${loader.slice(0, end + '\n}));'.length)}\nmodule.exports = ${m[1]}();\n`;
		}
	}
	return null;
}

// ─── Host threads ───

interface ThreadInit {
	runtime: string;
	modules: Record<string, { code?: string; json?: unknown; deps: Record<string, string | null> }>;
	env: Record<string, string>;
	plugins: boolean;
	fsBufferSize: number;
	crash: { crashFlag?: unknown; addonCrashFlag?: unknown };
}

interface HostThread {
	threadId: number;
	postMessage(msg: unknown, transfer?: unknown[]): void;
	terminate(): Promise<number>;
	ref(): void;
	unref(): void;
}

interface ThreadSink {
	message(data: unknown): void;
	error(err: unknown): void;
	exit(code: number): void;
	online(): void;
}

let threadBlobUrl: string | null = null;
let nextBrowserThreadId = 1;

function spawnHostThread(init: ThreadInit, sink: ThreadSink): HostThread {
	const wt = hostWorkerThreads();
	if (wt) {
		const w = new wt.Worker(NAPI_WASI_THREAD_SOURCE, { eval: true, workerData: init, name: 'lifo-wasi-thread' });
		w.on('message', (d) => sink.message(d));
		w.on('error', (e) => sink.error(e));
		w.on('exit', (code) => sink.exit(code as number));
		w.on('online', () => sink.online());
		return {
			threadId: w.threadId,
			postMessage: (m, t) => w.postMessage(m, t),
			terminate: () => w.terminate(),
			ref: () => w.ref(),
			unref: () => w.unref(),
		};
	}

	threadBlobUrl ??= URL.createObjectURL(new Blob([NAPI_WASI_THREAD_SOURCE], { type: 'text/javascript' }));
	const w = new Worker(threadBlobUrl, { name: 'lifo-wasi-thread' });
	let exited = false;
	const exit = (code: number) => {
		if (exited) return;
		exited = true;
		sink.exit(code);
	};
	w.onmessage = (e) => sink.message(e.data);
	w.onerror = (e) => {
		e.preventDefault?.();
		sink.error(new Error(e.message || 'WASI thread failed'));
	};
	w.onmessageerror = () => sink.error(new Error('WASI thread: a message could not be deserialized'));
	w.postMessage({ __lifo_init__: init });
	queueMicrotask(() => sink.online());
	return {
		threadId: nextBrowserThreadId++,
		postMessage: (m, t) => w.postMessage(m, (t ?? []) as Transferable[]),
		terminate: () => {
			w.terminate();
			queueMicrotask(() => exit(1));
			return Promise.resolve(1);
		},
		ref: () => {},
		unref: () => {},
	};
}

// ─── The box side ───

export interface NapiWasiHost {
	/** The box's `fs` module (the one `require('fs')` returns in this run). */
	getFs(): Record<string, unknown>;
	env: Record<string, string>;
	stdout: { write(s: string): void };
	stderr: { write(s: string): void };
	/** This run's pending-work tracker: async addon calls keep the run alive. */
	activity?: ActivityTracker;
	readFile(path: string): string;
	exists(path: string): boolean;
	/** Resolve like `require` from `fromDir`: a VFS path, `builtin:<name>`, or null. */
	resolve(spec: string, fromDir: string): string | null;
	/** A module's source as `(function (exports, require, module, …) { … })`, ESM turned to CommonJS. */
	compile(source: string, filename: string): string;
	/** Run `source` as a CommonJS module of this run, named `filename`; its exports. */
	evaluate(source: string, filename: string): unknown;
}

export interface NapiWasiRuntime {
	/**
	 * The `wasi` and `worker_threads` modules the napi-rs WASI loader at `loaderPath` gets
	 * instead of the builtins. Throws (after saying why on stderr) where threads can't run.
	 */
	modulesFor(loaderPath: string, loaderRequire: (id: string) => unknown): { wasi: unknown; worker_threads: unknown };
	/** Count the addon's promise-returning calls as pending work for this run. */
	trackExports(exports: unknown): void;
	/** End every thread this run started. */
	dispose(): void;
}

const REQUIRE_RE = /(?:\brequire|__lifoRequire)\s*\(\s*(['"])([^'"\n]+)\1\s*\)/g;

function dirOf(p: string): string {
	const i = p.lastIndexOf('/');
	return i <= 0 ? '/' : p.slice(0, i);
}

/** `@scope/name` or `name` from a path inside node_modules (the path itself otherwise). */
function packageNameOf(path: string): string {
	const i = path.lastIndexOf('/node_modules/');
	if (i === -1) return path;
	const [a, b] = path.slice(i + '/node_modules/'.length).split('/');
	return a.startsWith('@') && b ? `${a}/${b}` : a;
}

function stringEnv(env: Record<string, string>): Record<string, string> {
	const out: Record<string, string> = {};
	for (const [k, v] of Object.entries(env)) if (typeof v === 'string') out[k] = v;
	return out;
}

class NapiWasiWorker extends EventEmitter {
	threadId: number;
	private readonly thread: HostThread;
	/** Ended by the run (dispose), not by the addon: its exit isn't news to anyone. */
	private disposed = false;

	constructor(runtime: RuntimeState, filename: string, options?: { workerData?: Record<string, unknown> }) {
		super();
		const init = runtime.threadInit(filename, options?.workerData);
		this.thread = spawnHostThread(init, {
			message: (data) => {
				if (runtime.fsServer.handle(data)) return;
				const d = data as { __lifo_stdio__?: { fd: number; text: string }; __lifo_thread_error__?: { message: string } } | null;
				if (d?.__lifo_stdio__) {
					(d.__lifo_stdio__.fd === 1 ? runtime.host.stdout : runtime.host.stderr).write(d.__lifo_stdio__.text);
					return;
				}
				if (d?.__lifo_thread_error__) {
					runtime.host.stderr.write(`[lifo] a WASI thread failed to start: ${d.__lifo_thread_error__.message}\n`);
					return;
				}
				this.emit('message', data);
			},
			error: (err) => {
				if (!this.disposed) this.emit('error', err);
			},
			exit: (code) => {
				runtime.workers.delete(this);
				if (!this.disposed) this.emit('exit', code);
			},
			online: () => this.emit('online'),
		});
		this.threadId = this.thread.threadId;
		runtime.workers.add(this);
	}

	postMessage(msg: unknown, transfer?: unknown[]): void {
		this.thread.postMessage(msg, transfer);
	}

	terminate(): Promise<number> {
		return this.thread.terminate();
	}

	/** End the thread because the run is over, without reporting it to the addon. */
	dispose(): void {
		this.disposed = true;
		this.removeAllListeners();
		void this.thread.terminate();
	}

	ref(): void {
		this.thread.ref();
	}

	unref(): void {
		this.thread.unref();
	}
}

interface RuntimeState {
	host: NapiWasiHost;
	fsServer: FsServer;
	workers: Set<NapiWasiWorker>;
	threadInit(workerScript: string, workerData?: Record<string, unknown>): ThreadInit;
}

export function createNapiWasiRuntime(host: NapiWasiHost): NapiWasiRuntime {
	const bundles = new Map<string, Pick<ThreadInit, 'runtime' | 'modules'>>();
	/** Loaders that carry their runtime, by directory (their threads' scripts sit beside them). */
	const embedded = new Map<string, { file: string; source: string }>();

	/** A loader's runtime when it carries one (see embeddedRuntimeSource), remembered for its threads. */
	function embeddedRuntime(loaderPath: string): { file: string; source: string } | null {
		const dir = dirOf(loaderPath);
		const known = embedded.get(dir);
		if (known) return known;
		let source: string | null = null;
		try {
			source = embeddedRuntimeSource(host.readFile(loaderPath));
		} catch { /* unreadable: take the package's runtime */ }
		if (!source) return null;
		const runtime = { file: `${loaderPath}#napi-rs-runtime`, source };
		embedded.set(dir, runtime);
		return runtime;
	}

	/** The package's napi-rs runtime and everything it requires, compiled for a thread. */
	function runtimeBundle(pkgDir: string): Pick<ThreadInit, 'runtime' | 'modules'> {
		const inline = embedded.get(pkgDir);
		if (inline) {
			const cached = bundles.get(inline.file);
			if (cached) return cached;
			const bundle = { runtime: inline.file, modules: { [inline.file]: { code: host.compile(inline.source, inline.file), deps: {} } } };
			bundles.set(inline.file, bundle);
			return bundle;
		}
		const entry = host.resolve('@napi-rs/wasm-runtime', pkgDir);
		if (!entry || entry.startsWith('builtin:')) {
			throw new Error(`[lifo] @napi-rs/wasm-runtime is not installed for ${pkgDir}`);
		}
		const cached = bundles.get(entry);
		if (cached) return cached;
		const modules: ThreadInit['modules'] = {};
		const queue = [entry];
		while (queue.length > 0) {
			const file = queue.pop()!;
			if (modules[file]) continue;
			const source = host.readFile(file);
			if (file.endsWith('.json')) {
				modules[file] = { json: JSON.parse(source), deps: {} };
				continue;
			}
			const code = host.compile(source, file);
			const deps: Record<string, string | null> = {};
			for (const m of code.matchAll(REQUIRE_RE)) {
				const spec = m[2];
				if (spec in deps) continue;
				const target = host.resolve(spec, dirOf(file));
				deps[spec] = target;
				if (target && !target.startsWith('builtin:') && !modules[target]) queue.push(target);
			}
			modules[file] = { code, deps };
		}
		const bundle = { runtime: entry, modules };
		bundles.set(entry, bundle);
		return bundle;
	}

	const state: RuntimeState = {
		host,
		fsServer: createFsServer(() => host.getFs()),
		workers: new Set(),
		threadInit(workerScript, workerData) {
			// Bindings that link emnapi's "basic" archive pass the JS async-work and TSFN plugins
			// on every thread; do what the package's own worker script does.
			let plugins = false;
			try {
				if (host.exists(workerScript)) plugins = /emnapiAsyncWorkPlugin/.test(host.readFile(workerScript));
			} catch { /* no worker script: no plugins */ }
			return {
				...runtimeBundle(dirOf(workerScript)),
				env: stringEnv(host.env),
				plugins,
				fsBufferSize: 64 * 1024,
				crash: { crashFlag: workerData?.crashFlag, addonCrashFlag: workerData?.addonCrashFlag },
			};
		},
	};

	const print = (stream: { write(s: string): void }) => (...a: unknown[]) => stream.write(a.map(String).join(' ') + '\n');

	const warned = new Set<string>();

	return {
		modulesFor(loaderPath, loaderRequire) {
			const unavailable = wasmThreadsUnavailable();
			if (unavailable) {
				// The package's own loader turns this into "Cannot find native binding" (or
				// takes a JS fallback), so say once what actually went wrong.
				const pkg = packageNameOf(loaderPath);
				const err = new Error(`[lifo] ${pkg} needs WebAssembly threads, and ${unavailable}`) as Error & { code: string };
				err.code = 'ERR_LIFO_WASM_THREADS';
				if (!warned.has(pkg)) {
					warned.add(pkg);
					host.stderr.write(`${err.message}\n`);
				}
				throw err;
			}
			// The runtime the loader was built with: inside it, or its @napi-rs/wasm-runtime.
			const inline = embeddedRuntime(loaderPath);
			let runtime: { WASI: new (o: Record<string, unknown>) => unknown } | undefined;
			function LifoWASI(options?: Record<string, unknown>) {
				const rt = (runtime ??= (inline
					? host.evaluate(inline.source, inline.file)
					: loaderRequire('@napi-rs/wasm-runtime')) as { WASI: new (o: Record<string, unknown>) => unknown });
				return new rt.WASI({
					...(options ?? {}),
					version: 'preview1',
					env: stringEnv((options?.env as Record<string, string> | undefined) ?? host.env),
					preopens: { '/': '/' },
					fs: host.getFs(),
					print: print(host.stdout),
					printErr: print(host.stderr),
				});
			}
			function Worker(filename: string, options?: { workerData?: Record<string, unknown> }) {
				return new NapiWasiWorker(state, String(filename), options);
			}
			return {
				wasi: { WASI: LifoWASI },
				worker_threads: { Worker, isMainThread: true, parentPort: null, workerData: null, threadId: 0 },
			};
		},

		trackExports(exports) {
			const activity = host.activity;
			if (!activity || !exports || typeof exports !== 'object') return;
			const wrap = (fn: (...a: unknown[]) => unknown) =>
				function (this: unknown, ...args: unknown[]) {
					const r = fn.apply(this, args);
					if (r && typeof (r as Promise<unknown>).then === 'function') {
						const end = activity.begin();
						(r as Promise<unknown>).then(end, end);
					}
					return r;
				};
			const seen = new Set<object>();
			const target = exports as Record<string, unknown>;
			for (const key of Object.keys(target)) {
				const value = target[key];
				if (typeof value !== 'function') continue;
				const proto = (value as { prototype?: object }).prototype;
				const methods = proto ? Object.getOwnPropertyNames(proto).filter((k) => k !== 'constructor') : [];
				if (methods.length > 0 && proto) {
					// A class: wrap its methods (bundle.generate() and the like).
					if (seen.has(proto)) continue;
					seen.add(proto);
					for (const name of methods) {
						const d = Object.getOwnPropertyDescriptor(proto, name);
						if (!d || typeof d.value !== 'function' || !d.writable) continue;
						Object.defineProperty(proto, name, { ...d, value: wrap(d.value) });
					}
				} else if (!/^[A-Z]/.test(value.name)) {
					// A function (napi-rs exports functions camelCase, classes PascalCase).
					try {
						target[key] = wrap(value as (...a: unknown[]) => unknown);
					} catch { /* read-only export */ }
				}
			}
		},

		dispose() {
			for (const w of [...state.workers]) {
				try {
					w.dispose();
				} catch { /* already gone */ }
			}
			state.workers.clear();
		},
	};
}
